'use strict';
// BUG-431 review follow-up, 2026-09-10. Cards and jobs must report the same
// selected artifact, including a replacement generated by their review retry.
// Mutation 2026-09-10: remove either completion field or retry metadata -> red.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { createFsStore } = require('../src/core/memory/fs-store');
const { createPipelineEffector } = require('../src/core/effectors/pipeline');
const { createKanbanEffector } = require('../src/core/effectors/kanban');
const { createAgentActions } = require('../src/core/effectors/agent-actions');
const { tempVaultDir, cleanupVaultDir } = require('./helpers');
for (const surface of ['pipeline', 'kanban']) for (const [initial, replacement] of [[true, null], [false, null], [false, true], [true, false]]) {
  test(`${surface}: initial fallback=${initial}, review replacement=${replacement}`, async () => {
    const dir = tempVaultDir();
    const fs = createFsStore(() => dir, null), pipeline = createPipelineEffector({ fs }), kanban = createKanbanEffector({ fs });
    let run, reviews = 0, regenerated = 0;
    const job = { id: 'model-test', engine: 'dsh', laneFallback: initial, researchStatus: 'not-required' };
    const brain = { think: async args => {
      const reject = args.source === 'reviewer-agent' && ++reviews === 1 && replacement !== null;
      return { content: '{}', parsed: { verdict: reject ? 'reject' : 'approve', issues: reject ? ['Missing keyboard controls'] : [] } };
    } };
    const actions = createAgentActions({ fs, pipeline, kanban, brain,
      buildRunner: { getJob: () => null, enqueue: spec => { run = spec.run; return job; } },
      buildEngine: { generate: async () => { regenerated++; return { content: '<h1>replacement</h1>', engine: 'dsh', laneFallback: replacement }; } },
      evidenceValidator: { verify: () => ({ pass: true }) },
    });
    try {
      const title = 'Build a static greeting page'; let id;
      if (surface === 'pipeline') { const card = pipeline.capture(title, 'test'); id = card.id; pipeline.approve(id); actions.executePipelineCard(id); }
      else { const card = kanban.addCard(title, 'backlog'); id = card.id; actions.buildKanbanCard(id); }
      await run('<h1>initial</h1>', job, title);
      const card = surface === 'pipeline' ? pipeline.findCard(id).card : kanban.findCard(id);
      const expected = replacement === null ? initial : replacement;
      assert.equal(regenerated, replacement === null ? 0 : 1);
      assert.equal(job.laneFallback, expected);
      assert.equal(card.status, expected ? 'needs-work' : 'done');
      if (surface === 'pipeline') assert.equal(card.evidence.pass, !expected);
    } finally { cleanupVaultDir(dir); }
  });
}
